import office from './maps/office.json' with { type: 'json' };
import lounge from './maps/lounge.json' with { type: 'json' };
import home from './maps/home.json' with { type: 'json' };
import { parseMap, type OfficeMap } from './map.ts';

/**
 * Maps that ship with the app, generated by `tools/build_maps.py` into `./maps/<id>.json`.
 * They are listed and playable even with an empty store; a saved map with the same id (an
 * edited copy) takes precedence, and deleting it brings the built-in back.
 */
export const BUILT_IN_MAPS: readonly OfficeMap[] = [office, lounge, home].map((data) => {
  const map = parseMap(data);
  if (!map) throw new Error('invalid built-in map');
  return map;
});

export const OFFICE_MAP: OfficeMap = BUILT_IN_MAPS[0]!;

export function builtInMap(id: string): OfficeMap | null {
  return BUILT_IN_MAPS.find((m) => m.id === id) ?? null;
}
